import { describe, it, expect } from 'vitest'
import { readFileSync } from 'node:fs'
import { resolve, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import * as v1 from './v1'
import { REPORT, ReportInvalid, type ReportKey } from './report'

// The report bundle against #report_bundle and its four seal vectors (generated by an independent Python
// implementation; the generic per-purpose checks are v1.conformance.test.ts's). Here: the three plaintext layouts both
// ways, each refusal the decoder and the encoder owe, and the property the CR's phase-1 bite names — a report sealed to
// epoch n does not open with epoch n+1's key.

const unhex = (s: string) => Uint8Array.from(Buffer.from(s, 'hex'))
const hex = (u: Uint8Array) => Buffer.from(u).toString('hex')
const here = dirname(fileURLToPath(import.meta.url))
const vectors = JSON.parse(readFileSync(resolve(here, '../../../../contracts/crypto/vectors/v1.json'), 'utf8'))
const bundle = vectors.report_bundle

type EntryVector = { role: string; ref: string | null; key: string }
const entries = (i: number): ReportKey[] =>
  bundle.keys[i].entries.map((e: EntryVector) => ({ role: e.role, ref: e.ref, key: unhex(e.key) }))
const body = (): v1.ReportBody => ({
  reportKey: unhex(bundle.body.report_key),
  reason: bundle.body.reason,
  context: bundle.body.context,
})
const u32 = (n: number) => {
  const b = new Uint8Array(4)
  new DataView(b.buffer).setUint32(0, n, false)
  return b
}
const lp = (b: Uint8Array) => v1.concat(u32(b.length), b)
const key = (n: number) => new Uint8Array(32).fill(n)
const ID = '3f2504e0-4f89-41d3-9a0c-0305e82c3301'
const SHARE = 'Abcdefghijklmnopqrstuvwxyz0123456789_-ABCDE'

it('names its refusal', () => {
  const e = new ReportInvalid('key')
  expect(e.message).toBe('report_invalid: key')
  expect(e.name).toBe('ReportInvalid')
  expect(e).toBeInstanceOf(Error)
})

describe('report keys (a report share\'s plaintext)', () => {
  it.each([0, 1])('encodes vector %i to its bytes and decodes them back', (i) => {
    expect(hex(v1.encodeReportKeys(entries(i)))).toBe(bundle.keys[i].encoded)
    expect(v1.decodeReportKeys(unhex(bundle.keys[i].encoded))).toEqual(entries(i))
  })

  it('the seal vectors carry exactly these plaintexts', () => {
    expect(vectors.seal.sym['report-share'].plaintext).toBe(bundle.keys[0].encoded)
    expect(vectors.seal.sym['report-link'].plaintext).toBe(bundle.keys[1].encoded)
  })

  it('takes one key and the maximum, and refuses none and one more', () => {
    const one = [{ role: 'NODE', ref: null, key: key(1) }]
    expect(v1.decodeReportKeys(v1.encodeReportKeys(one))).toEqual(one)
    const max = Array.from({ length: REPORT.maxKeysPerShare }, (_, i) => ({ role: 'BLOB', ref: ID, key: key(i) }))
    expect(v1.decodeReportKeys(v1.encodeReportKeys(max))).toHaveLength(REPORT.maxKeysPerShare)
    expect(() => v1.encodeReportKeys([])).toThrow(new ReportInvalid('key count'))
    expect(() => v1.encodeReportKeys([...max, max[0]])).toThrow(new ReportInvalid('key count'))
  })

  it('seals its largest share to exactly the length the contract admits for one item', () => {
    // Inbox #540: the cap and the wire's bound move together. The worst case is every role 16 bytes and every ref a UUID.
    const contract = readFileSync(resolve(here, '../../../../contracts/api/_common.openapi.yaml'), 'utf8')
    const bound = /sealedShare:[\s\S]*?maxLength: (\d+)[\s\S]*?Size\(max = (\d+)\)/.exec(contract)
    const admitted = Number(bound?.[1])
    expect(Number(bound?.[2])).toBe(admitted)
    expect(REPORT.maxKeysPerShare).toBe(256)
    const worst = Array.from({ length: REPORT.maxKeysPerShare }, (_, i) => ({ role: 'ENTRY_REVISION_XY', ref: ID, key: key(i) }))
    worst.forEach((k) => (k.role = k.role.slice(0, 16)))
    const sealed = v1.sealReportShare(new Uint8Array(32).fill(7), { kind: 'ITEM', id: ID }, worst)
    expect(Buffer.from(sealed).toString('base64')).toHaveLength(admitted)
  })

  it.each([
    ['a lower-case role', { role: 'node', ref: null, key: key(1) }, 'role'],
    ['a role of seventeen characters', { role: 'A'.repeat(17), ref: null, key: key(1) }, 'role'],
    ['a role that is no string', { role: 7 as unknown as string, ref: null, key: key(1) }, 'role'],
    ['a ref that is no UUID', { role: 'BLOB', ref: ID.toUpperCase(), key: key(1) }, 'ref'],
    ['a ref that is no string', { role: 'BLOB', ref: 7 as unknown as string, key: key(1) }, 'ref'],
    ['a boxed String role', { role: new String('NODE') as unknown as string, ref: null, key: key(1) }, 'role'],
    ['a boxed String ref', { role: 'BLOB', ref: new String(ID) as unknown as string, key: key(1) }, 'ref'],
    ['a ref with a character before the UUID', { role: 'BLOB', ref: 'x' + ID, key: key(1) }, 'ref'],
    ['a ref with a character after the UUID', { role: 'BLOB', ref: ID + 'x', key: key(1) }, 'ref'],
    ['a key of 31 bytes', { role: 'NODE', ref: null, key: new Uint8Array(31) }, 'key'],
    ['a key that is no byte array', { role: 'NODE', ref: null, key: Array(32).fill(0) as unknown as Uint8Array }, 'key'],
  ])('refuses to write %s', (_, k, detail) => {
    expect(() => v1.encodeReportKeys([k as ReportKey])).toThrow(new ReportInvalid(detail))
  })

  const entry = (role: Uint8Array, ref: Uint8Array, k: Uint8Array) => v1.concat(lp(role), lp(ref), lp(k))
  it.each([
    ['no count at all', new Uint8Array(3), 'truncated'],
    ['a zero count', u32(0), 'key count'],
    ['a count above the maximum', u32(REPORT.maxKeysPerShare + 1), 'key count'],
    ['an entry cut short', v1.concat(u32(1), u32(4), v1.utf8('NO')), 'truncated'],
    ['a role that is not UTF-8', v1.concat(u32(1), entry(Uint8Array.of(0xff), new Uint8Array(0), key(1))), 'role is not UTF-8'],
    ['a role off the token', v1.concat(u32(1), entry(v1.utf8('no-de'), new Uint8Array(0), key(1))), 'role'],
    ['a ref that is not UTF-8', v1.concat(u32(1), entry(v1.utf8('BLOB'), Uint8Array.of(0xff), key(1))), 'ref is not UTF-8'],
    ['a ref that is no UUID', v1.concat(u32(1), entry(v1.utf8('BLOB'), v1.utf8('x'), key(1))), 'ref'],
    ['a ref with a character before the UUID', v1.concat(u32(1), entry(v1.utf8('BLOB'), v1.utf8('x' + ID), key(1))), 'ref'],
    ['a ref with a character after the UUID', v1.concat(u32(1), entry(v1.utf8('BLOB'), v1.utf8(ID + 'x'), key(1))), 'ref'],
    ['a last field that runs past the end', v1.concat(u32(1), lp(v1.utf8('NODE')), lp(new Uint8Array(0)), u32(32), new Uint8Array(31)), 'truncated'],
    ['a key of 33 bytes', v1.concat(u32(1), entry(v1.utf8('NODE'), new Uint8Array(0), new Uint8Array(33))), 'key'],
    ['a byte after the last entry', v1.concat(u32(1), entry(v1.utf8('NODE'), new Uint8Array(0), key(1)), Uint8Array.of(0)), 'trailing bytes'],
  ])('refuses to read %s', (_, bytes, detail) => {
    expect(() => v1.decodeReportKeys(bytes)).toThrow(new ReportInvalid(detail))
  })

  it('reads a role and a ref as UTF-8, a second entry after the first', () => {
    const two = [
      { role: 'MEDIA_META', ref: null, key: key(2) },
      { role: 'BLOB', ref: ID, key: key(3) },
    ]
    expect(v1.decodeReportKeys(v1.encodeReportKeys(two))).toEqual(two)
  })
})

describe('the report body (the sealed part\'s plaintext)', () => {
  it('encodes the vector to its bytes — the reason composed (NFC) — and decodes them back', () => {
    expect(hex(v1.encodeReportBody(body()))).toBe(bundle.body.encoded)
    expect(vectors.seal.asym['moderation-report'].plaintext).toBe(bundle.body.encoded)
    const back = v1.decodeReportBody(unhex(bundle.body.encoded))
    expect(back.reason).toBe(bundle.body.reason.normalize('NFC'))
    expect(back.reason).not.toBe(bundle.body.reason)
    expect({ ...back, reason: bundle.body.reason }).toEqual(body())
  })

  it('pads to the bucket: the length says which bucket, never the length of a text', () => {
    const short = v1.encodeReportBody({ ...body(), reason: 'x', context: '' })
    const longer = v1.encodeReportBody({ ...body(), reason: 'x'.repeat(400), context: '' })
    expect(short.length).toBe(REPORT.bucketBytes)
    expect(longer.length).toBe(REPORT.bucketBytes)
    expect(short.slice(4 + 32 + 4 + 1).every((b) => b === 0)).toBe(true)
    const next = v1.encodeReportBody({ ...body(), reason: 'x'.repeat(REPORT.bucketBytes), context: '' })
    expect(next.length).toBe(2 * REPORT.bucketBytes)
  })

  it('takes each text at its bound and refuses one byte more', () => {
    const at = { ...body(), reason: 'r'.repeat(REPORT.reasonBytes), context: 'x'.repeat(REPORT.contextBytes) }
    expect(v1.decodeReportBody(v1.encodeReportBody(at))).toEqual(at)
    expect(() => v1.encodeReportBody({ ...at, reason: at.reason + 'r' })).toThrow(new ReportInvalid('reason'))
    expect(() => v1.encodeReportBody({ ...at, context: at.context + 'x' })).toThrow(new ReportInvalid('context'))
  })

  it('refuses a blank reason, and a report key that is not 32 bytes', () => {
    expect(() => v1.encodeReportBody({ ...body(), reason: ' \n ' })).toThrow(new ReportInvalid('reason'))
    expect(() => v1.encodeReportBody({ ...body(), reportKey: new Uint8Array(31) })).toThrow(new ReportInvalid('report key'))
    expect(() => v1.encodeReportBody({ ...body(), reportKey: Array(32).fill(0) as unknown as Uint8Array })).toThrow(
      new ReportInvalid('report key'),
    )
  })

  const fields = (rk: Uint8Array, ...texts: Uint8Array[]) => v1.concat(lp(rk), ...texts.map(lp))
  const padded = (b: Uint8Array) => {
    const out = new Uint8Array(Math.ceil(b.length / REPORT.bucketBytes) * REPORT.bucketBytes)
    out.set(b)
    return out
  }
  it.each([
    ['a length off the bucket', new Uint8Array(REPORT.bucketBytes - 1), 'padding'],
    ['a field running past the end', padded(v1.concat(u32(REPORT.bucketBytes))), 'truncated'],
    ['a report key of 31 bytes', padded(fields(new Uint8Array(31), v1.utf8('r'), v1.utf8(''))), 'report key'],
    ['a reason that is not UTF-8', padded(fields(key(1), Uint8Array.of(0xff), v1.utf8(''))), 'reason is not UTF-8'],
    ['a context that is not UTF-8', padded(fields(key(1), v1.utf8('r'), Uint8Array.of(0xff))), 'context is not UTF-8'],
  ])('refuses to read %s', (_, bytes, detail) => {
    expect(() => v1.decodeReportBody(bytes)).toThrow(new ReportInvalid(detail))
  })

  it('refuses padding that is not zeros', () => {
    const bytes = v1.encodeReportBody(body())
    bytes[bytes.length - 1] = 1
    expect(() => v1.decodeReportBody(bytes)).toThrow(new ReportInvalid('padding'))
  })
})

describe('the reporter\'s contact (sealed apart, ADR 0093 § 11)', () => {
  it('encodes the vector to its bytes and decodes them back', () => {
    expect(hex(v1.encodeReportContact(bundle.contact.contact))).toBe(bundle.contact.encoded)
    expect(vectors.seal.asym['moderation-report-contact'].plaintext).toBe(bundle.contact.encoded)
    expect(v1.decodeReportContact(unhex(bundle.contact.encoded))).toBe(bundle.contact.contact)
  })

  it('is one bucket whatever its length, takes its bound and refuses one byte more or a blank', () => {
    expect(v1.encodeReportContact('a@b.c').length).toBe(REPORT.bucketBytes)
    const at = 'c'.repeat(REPORT.contactBytes)
    expect(v1.encodeReportContact(at).length).toBe(REPORT.bucketBytes)
    expect(v1.decodeReportContact(v1.encodeReportContact(at))).toBe(at)
    expect(() => v1.encodeReportContact(at + 'c')).toThrow(new ReportInvalid('contact'))
    expect(() => v1.encodeReportContact(' \n ')).toThrow(new ReportInvalid('contact'))
  })

  it('refuses a length off the bucket, a contact that is not UTF-8, and padding that is not zeros', () => {
    expect(() => v1.decodeReportContact(new Uint8Array(REPORT.bucketBytes * 2))).toThrow(new ReportInvalid('padding'))
    const bad = new Uint8Array(REPORT.bucketBytes)
    bad.set(lp(Uint8Array.of(0xff)))
    expect(() => v1.decodeReportContact(bad)).toThrow(new ReportInvalid('contact is not UTF-8'))
    const dirty = v1.encodeReportContact('a@b.c')
    dirty[dirty.length - 1] = 1
    expect(() => v1.decodeReportContact(dirty)).toThrow(new ReportInvalid('padding'))
  })

  it('opens with its epoch\'s key and not as the report\'s body, nor the body as a contact', () => {
    const m = unhex(vectors.moderation_key.m)
    const kem = v1.moderationBundle(m).kem
    const sk = v1.moderationKemSecret(m)
    const sealed = v1.sealReportContact(4, kem, 'reporter@example.com')
    expect(v1.openReportContact(4, sk, sealed)).toBe('reporter@example.com')
    expect(() => v1.openReportContact(5, sk, sealed)).toThrow(new v1.OpenRefused('moderation-report-contact'))
    expect(() => v1.openReport(4, sk, sealed)).toThrow(new v1.OpenRefused('moderation-report'))
    expect(() => v1.openReportContact(4, sk, v1.sealReport(4, kem, body()))).toThrow(new v1.OpenRefused('moderation-report-contact'))
  })
})

describe('sealing a report to the moderation key', () => {
  const m = unhex(vectors.moderation_key.m)
  const next = new Uint8Array(32).fill(0x77)

  it('a report sealed to epoch n opens with epoch n\'s key, at epoch n', () => {
    const sealed = v1.sealReport(4, v1.moderationBundle(m).kem, body())
    expect(v1.openReport(4, v1.moderationKemSecret(m), sealed)).toEqual(v1.decodeReportBody(v1.encodeReportBody(body())))
  })

  // The phase-1 bite (cr-report-and-hold): a rotation protects every report after it, and a report stays sealed to
  // the epoch it was made under (ADR 0099 § 4) — so neither the next epoch's key nor the next epoch's address opens it.
  it('a report sealed to epoch n does not open with epoch n+1\'s key, nor at epoch n+1', () => {
    const sealed = v1.sealReport(4, v1.moderationBundle(m).kem, body())
    expect(() => v1.openReport(4, v1.moderationKemSecret(next), sealed)).toThrow(new v1.OpenRefused('moderation-report'))
    expect(() => v1.openReport(5, v1.moderationKemSecret(next), sealed)).toThrow(new v1.OpenRefused('moderation-report'))
    expect(() => v1.openReport(5, v1.moderationKemSecret(m), sealed)).toThrow(new v1.OpenRefused('moderation-report'))
  })

  it('a moderation grant does not open as a report, nor a report as a grant', () => {
    const sk = v1.moderationKemSecret(m)
    const kem = v1.moderationBundle(m).kem
    const grant = v1.sealTo({ purpose: 'moderation-grant', epoch: 4 }, kem, v1.encodeReportBody(body()))
    expect(() => v1.openReport(4, sk, grant)).toThrow(new v1.OpenRefused('moderation-report'))
    const report = v1.sealReport(4, kem, body())
    expect(() => v1.openAs({ purpose: 'moderation-grant', epoch: 4 }, sk, report)).toThrow(new v1.OpenRefused('moderation-grant'))
  })
})

describe('report shares', () => {
  const rk = unhex(bundle.body.report_key)

  it('opens the vectors\' blobs by the item they are addressed by', () => {
    const node = vectors.seal.sym['report-share']
    expect(v1.openReportShare(rk, { kind: 'NODE', id: node.context.itemId }, unhex(node.blob))).toEqual(entries(0))
    const link = vectors.seal.sym['report-link']
    expect(v1.openReportShare(rk, { kind: 'LINK', shareId: link.context.shareId }, unhex(link.blob))).toEqual(entries(1))
  })

  it('round-trips each kind, and a share does not open as another item, kind or report', () => {
    for (const item of [{ kind: 'NODE', id: ID }, { kind: 'ITEM', id: ID }, { kind: 'NAME', id: ID }, { kind: 'LINK', shareId: SHARE }] as const) {
      const sealed = v1.sealReportShare(rk, item, entries(0))
      expect(v1.openReportShare(rk, item, sealed)).toEqual(entries(0))
      expect(() => v1.openReportShare(key(9), item, sealed)).toThrow(v1.OpenRefused)
    }
    const sealed = v1.sealReportShare(rk, { kind: 'NODE', id: ID }, entries(0))
    expect(() => v1.openReportShare(rk, { kind: 'ITEM', id: ID }, sealed)).toThrow(new v1.OpenRefused('report-share'))
    // A node's name reported on its own is another item than the node: its share opens as neither the other way round.
    expect(() => v1.openReportShare(rk, { kind: 'NAME', id: ID }, sealed)).toThrow(new v1.OpenRefused('report-share'))
    expect(() => v1.openReportShare(rk, { kind: 'NODE', id: ID }, v1.sealReportShare(rk, { kind: 'NAME', id: ID }, entries(0)))).toThrow(
      new v1.OpenRefused('report-share'),
    )
    expect(() => v1.openReportShare(rk, { kind: 'NODE', id: ID.replace(/1$/, '2') }, sealed)).toThrow(
      new v1.OpenRefused('report-share'),
    )
    expect(() => v1.openReportShare(rk, { kind: 'LINK', shareId: SHARE }, sealed)).toThrow(new v1.OpenRefused('report-link'))
  })

  it('a fresh report key per call', () => {
    const a = v1.newReportKey()
    expect(a).toHaveLength(REPORT.keyBytes)
    expect(hex(a)).not.toBe(hex(v1.newReportKey()))
  })
})

describe('moderation notes', () => {
  const vec = vectors.seal.asym['moderation-note']
  const sk = unhex(vectors.xwing.vectors[0].sk)
  const text = 'Held for the court: Az. 12 O 345/26 (Landgericht).'

  it('decodes the vector plaintext, and the encoder writes exactly it', () => {
    expect(v1.decodeModerationNote(unhex(vec.plaintext))).toBe(text)
    expect(hex(v1.encodeModerationNote(text))).toBe(vec.plaintext)
    expect(v1.openModerationNote(vec.context.epoch, vec.context.caseId, sk, unhex(vec.blob))).toBe(text)
  })

  it('pads to the bucket: one byte more than a bucket holds takes the next', () => {
    expect(v1.encodeModerationNote('a'.repeat(REPORT.bucketBytes - 4))).toHaveLength(REPORT.bucketBytes)
    expect(v1.encodeModerationNote('a'.repeat(REPORT.bucketBytes - 3))).toHaveLength(2 * REPORT.bucketBytes)
  })

  it('refuses a blank note and one above its bound, and takes one at it', () => {
    expect(() => v1.encodeModerationNote('  ')).toThrow(new ReportInvalid('note'))
    expect(() => v1.encodeModerationNote('a'.repeat(REPORT.noteBytes + 1))).toThrow(new ReportInvalid('note'))
    expect(v1.decodeModerationNote(v1.encodeModerationNote('a'.repeat(REPORT.noteBytes)))).toHaveLength(REPORT.noteBytes)
  })

  it('refuses padding that is not zeros, a length off the bucket, and a field past the end', () => {
    const p = unhex(vec.plaintext)
    p[p.length - 1] = 1
    expect(() => v1.decodeModerationNote(p)).toThrow(new ReportInvalid('padding'))
    expect(() => v1.decodeModerationNote(unhex(vec.plaintext).slice(1))).toThrow(new ReportInvalid('padding'))
    const long = new Uint8Array(REPORT.bucketBytes)
    long.set(u32(REPORT.bucketBytes))
    expect(() => v1.decodeModerationNote(long)).toThrow(new ReportInvalid('truncated'))
  })

  it('a note sealed for one case and epoch opens for no other', () => {
    const m = key(7)
    const kem = v1.moderationBundle(m).kem
    const sealed = v1.sealModerationNote(4, ID, kem, text)
    expect(v1.openModerationNote(4, ID, v1.moderationKemSecret(m), sealed)).toBe(text)
    expect(() => v1.openModerationNote(4, ID.replace(/1$/, '2'), v1.moderationKemSecret(m), sealed)).toThrow(
      new v1.OpenRefused('moderation-note'),
    )
    expect(() => v1.openModerationNote(5, ID, v1.moderationKemSecret(m), sealed)).toThrow(new v1.OpenRefused('moderation-note'))
    expect(() => v1.openReport(4, v1.moderationKemSecret(m), sealed)).toThrow(new v1.OpenRefused('moderation-report'))
  })
})

describe('statement facts and objections', () => {
  const sk = unhex(vectors.xwing.vectors[0].sk)
  const facts = vectors.seal.sym['moderation-statement-facts']
  const wrap = vectors.seal.asym['moderation-facts-key']
  const objection = vectors.seal.asym['moderation-objection']
  const OTHER = '7e8f9a0b-1c2d-4e3f-8a5b-6c7d8e9f0a1b'
  const STATEMENT = '5b6c7d8e-9f0a-4b1c-8d2e-3f4a5b6c7d8e'

  it('open their vectors: the key with the recipient identity, the facts with that key, the objection with the epoch key', () => {
    // The two facts vectors are one statement: the wrap's plaintext is the facts seal's key.
    expect(wrap.plaintext).toBe(facts.kek)
    expect(wrap.context).toEqual({ ...facts.context, accountId: OTHER })
    const k = v1.unwrapFactsKey(wrap.context.caseId, wrap.context.statementId, wrap.context.accountId, sk, unhex(wrap.blob))
    expect(hex(k)).toBe(facts.kek)
    const f = v1.openStatementFacts(facts.context.caseId, facts.context.statementId, k, unhex(facts.blob))
    expect(f).toBe("The photo shows a person's home address next to a threat.")
    expect(hex(v1.encodeModerationNote(f))).toBe(facts.plaintext)
    const o = v1.openObjection(objection.context.epoch, objection.context.statementId, sk, unhex(objection.blob))
    expect(o).toBe('This is my own address, posted with my consent; there is no threat.')
    expect(hex(v1.encodeModerationNote(o))).toBe(objection.plaintext)
  })

  it('a fresh facts key per call', () => {
    const a = v1.newFactsKey()
    expect(a).toHaveLength(REPORT.keyBytes)
    expect(hex(a)).not.toBe(hex(v1.newFactsKey()))
  })

  it('facts sealed once for one statement open for no other statement or case, nor under another key, nor as a note', () => {
    const k = key(9)
    const sealed = v1.sealStatementFacts(ID, STATEMENT, k, 'what was found')
    expect(v1.openStatementFacts(ID, STATEMENT, k, sealed)).toBe('what was found')
    expect(() => v1.openStatementFacts(ID, ID, k, sealed)).toThrow(new v1.OpenRefused('moderation-statement-facts'))
    expect(() => v1.openStatementFacts(STATEMENT, STATEMENT, k, sealed)).toThrow(new v1.OpenRefused('moderation-statement-facts'))
    expect(() => v1.openStatementFacts(ID, STATEMENT, key(8), sealed)).toThrow(new v1.OpenRefused('moderation-statement-facts'))
    expect(() => v1.open({ purpose: 'report-share', itemKind: 'NODE', itemId: ID }, k, sealed)).toThrow(
      new v1.OpenRefused('report-share'),
    )
    expect(() => v1.sealStatementFacts(ID, STATEMENT, k, ' ')).toThrow(new ReportInvalid('note'))
  })

  it('a facts key wrapped to one member opens for no other member, statement or case, and never as a note', () => {
    const m = key(9)
    const identity = v1.moderationBundle(m).kem
    const secret = v1.moderationKemSecret(m)
    const k = key(5)
    const wrapped = v1.wrapFactsKey(ID, STATEMENT, OTHER, identity, k)
    expect(wrapped).toHaveLength(1 + 1120 + 12 + REPORT.keyBytes + 16)
    expect(hex(v1.unwrapFactsKey(ID, STATEMENT, OTHER, secret, wrapped))).toBe(hex(k))
    const refused = new v1.OpenRefused('moderation-facts-key')
    expect(() => v1.unwrapFactsKey(ID, STATEMENT, ID, secret, wrapped)).toThrow(refused)
    expect(() => v1.unwrapFactsKey(ID, ID, OTHER, secret, wrapped)).toThrow(refused)
    expect(() => v1.unwrapFactsKey(STATEMENT, STATEMENT, OTHER, secret, wrapped)).toThrow(refused)
    expect(() => v1.unwrapFactsKey(ID, STATEMENT, OTHER, sk, wrapped)).toThrow(refused)
    expect(() => v1.openModerationNote(0, ID, secret, wrapped)).toThrow(new v1.OpenRefused('moderation-note'))
  })

  it('only a 32-byte key is sealed under, wrapped, or taken from a wrap', () => {
    const m = key(9)
    const identity = v1.moderationBundle(m).kem
    for (const bad of [new Uint8Array(31), new Uint8Array(33), Array.from(key(1)) as unknown as Uint8Array]) {
      expect(() => v1.sealStatementFacts(ID, STATEMENT, bad, 'what was found')).toThrow(new ReportInvalid('facts key'))
      expect(() => v1.wrapFactsKey(ID, STATEMENT, OTHER, identity, bad)).toThrow(new ReportInvalid('facts key'))
    }
    // An authentic wrap of something that is not a 32-byte key — the seal's own context, a 31-byte payload.
    const short = v1.sealTo({ purpose: 'moderation-facts-key', caseId: ID, statementId: STATEMENT, accountId: OTHER }, identity, new Uint8Array(31))
    expect(() => v1.unwrapFactsKey(ID, STATEMENT, OTHER, v1.moderationKemSecret(m), short)).toThrow(new ReportInvalid('facts key'))
  })

  it('a note, the facts or an objection whose text is not UTF-8 is refused by name', () => {
    const bad = new Uint8Array(REPORT.bucketBytes)
    bad.set(lp(Uint8Array.of(0xff, 0xfe)))
    expect(() => v1.decodeModerationNote(bad)).toThrow(new ReportInvalid('note is not UTF-8'))
  })

  it('an objection sealed for one statement and epoch opens for no other, and never as a note', () => {
    const m = key(8)
    const kem = v1.moderationBundle(m).kem
    const secret = v1.moderationKemSecret(m)
    const sealed = v1.sealObjection(2, ID, kem, 'I object')
    expect(v1.openObjection(2, ID, secret, sealed)).toBe('I object')
    expect(() => v1.openObjection(3, ID, secret, sealed)).toThrow(new v1.OpenRefused('moderation-objection'))
    expect(() => v1.openObjection(2, ID.replace(/1$/, '2'), secret, sealed)).toThrow(new v1.OpenRefused('moderation-objection'))
    expect(() => v1.openModerationNote(2, ID, secret, sealed)).toThrow(new v1.OpenRefused('moderation-note'))
    expect(() => v1.sealObjection(2, ID, kem, '')).toThrow(new ReportInvalid('note'))
  })
})

describe("a Server Owner's step facts", () => {
  const sk = unhex(vectors.xwing.vectors[0].sk)
  const step = vectors.seal.asym['moderation-step-facts']

  it('open their vector with the epoch key, as the note encoding', () => {
    const f = v1.openStepFacts(step.context.epoch, step.context.statementId, sk, unhex(step.blob))
    expect(f).toBe('The member posted the same unlawful image in three spaces after two warnings.')
    expect(hex(v1.encodeModerationNote(f))).toBe(step.plaintext)
  })

  it('facts sealed for one statement and epoch open for no other, and never as a note, an objection or an order', () => {
    const m = key(7)
    const kem = v1.moderationBundle(m).kem
    const secret = v1.moderationKemSecret(m)
    const sealed = v1.sealStepFacts(3, ID, kem, 'blocked over a terms breach')
    expect(v1.openStepFacts(3, ID, secret, sealed)).toBe('blocked over a terms breach')
    expect(() => v1.openStepFacts(4, ID, secret, sealed)).toThrow(new v1.OpenRefused('moderation-step-facts'))
    expect(() => v1.openStepFacts(3, ID.replace(/1$/, '2'), secret, sealed)).toThrow(new v1.OpenRefused('moderation-step-facts'))
    expect(() => v1.openModerationNote(3, ID, secret, sealed)).toThrow(new v1.OpenRefused('moderation-note'))
    expect(() => v1.openObjection(3, ID, secret, sealed)).toThrow(new v1.OpenRefused('moderation-objection'))
    expect(() => v1.openOrderReference(3, ID, secret, sealed)).toThrow(new v1.OpenRefused('moderation-order'))
    expect(() => v1.sealStepFacts(3, ID, kem, ' ')).toThrow(new ReportInvalid('note'))
  })
})

